    """Return an httpx.Client for base_url that sends all requests via the HTTP proxy at proxy_url,
    with a 5-second timeout and User-Agent 'inventory-sync/1.0' on every request."""
    proxies = {
        "http://": proxy_url,
        "https://": proxy_url,
    }
    headers = {
        "User-Agent": "inventory-sync/1.0",
    }
    timeout = 5.0
    client = httpx.Client(base_url=base_url, proxies=proxies, headers=headers, timeout=timeout)
    return client

