import re

def validate_signup(data: dict) -> dict:
    """
    Validate sign-up data with required fields:
    - username: alphanumeric string
    - email: valid email address
    Optional fields:
    - plan: one of "free", "pro", "team", default "free"
    - age: integer between 16 and 120 inclusive
    Unknown keys are dropped.
    On invalid input, raise ValueError with a 'messages' attribute mapping field names to list of errors.
    """
    errors = {}
    cleaned = {}

    # Validate username: required, alphanumeric string
    username = data.get("username")
    if username is None:
        errors.setdefault("username", []).append("Missing data for required field.")
    elif not isinstance(username, str):
        errors.setdefault("username", []).append("Must be a string.")
    elif not username.isalnum():
        errors.setdefault("username", []).append("Must be alphanumeric.")
    else:
        cleaned["username"] = username

    # Validate email: required, valid email address
    email = data.get("email")
    if email is None:
        errors.setdefault("email", []).append("Missing data for required field.")
    elif not isinstance(email, str):
        errors.setdefault("email", []).append("Must be a string.")
    else:
        # Simple email regex: one @, non-empty local and domain parts, domain has at least one dot
        # This is a reasonable heuristic without external libs
        if not re.fullmatch(r"[^@\s]+@[^@\s]+\.[^@\s]+", email):
            errors.setdefault("email", []).append("Invalid email address.")
        else:
            cleaned["email"] = email

    # Validate plan: optional, default "free", must be one of "free", "pro", "team"
    plan = data.get("plan", "free")
    if not isinstance(plan, str):
        errors.setdefault("plan", []).append("Must be a string.")
    elif plan not in ("free", "pro", "team"):
        errors.setdefault("plan", []).append("Must be one of 'free', 'pro', 'team'.")
    else:
        cleaned["plan"] = plan

    # Validate age: optional, integer 16 to 120 inclusive
    if "age" in data:
        age = data["age"]
        if not isinstance(age, int):
            errors.setdefault("age", []).append("Must be an integer.")
        elif not (16 <= age <= 120):
            errors.setdefault("age", []).append("Must be between 16 and 120 inclusive.")
        else:
            cleaned["age"] = age

    if errors:
        exc = ValueError("Invalid input")
        exc.messages = errors
        raise exc

    return cleaned
